package io.github.ningpp.compat;

/** Replacement for System.DuplicateWaitObjectException (generated by CSharpToJava converter). */
public class DuplicateWaitObjectException extends IllegalArgumentException {
    public DuplicateWaitObjectException() { super(); }
    public DuplicateWaitObjectException(String message) { super(message); }
    public DuplicateWaitObjectException(String message, Throwable cause) { super(message, cause); }
}
